/**
 * AnA RI — Command Executor
 *
 * Gives AnA full operational control over the platform:
 * - Project lifecycle (create, update, list, switch)
 * - Document lifecycle (create, update, version, section-level edits)
 * - Task management (create, assign, update, complete, bulk)
 * - Artifact operations (create, place in dossier, promote, lock)
 * - Dossier packaging (readiness check, export)
 * - User context loading (history, preferences, work queue)
 *
 * Every command returns a structured result and logs to the audit trail.
 *
 * @module server/services/ana-ri/command-executor
 */

import { getPool } from '../../db';
import { projectBelongsToTenant } from '../cmc/project-membership';
import type { StatisticalInput } from '../ana-biostats/types';
import type { PoolClient } from 'pg';
import type { AuditTaskActionParams } from '../tasking/task-audit.js';
import type { TaskEventNotice } from '../tasking/task-side-effects.js';
import { logGeneration, validateArtifactQuality } from './enforcement.js';
import { executeGovernedAnaOperation } from '../governed-ana-execution.js';
import type { ArtifactWriteHook } from '../artifact-tagger.js';
import {
  artifactVersionContentBinding,
  assertVerifiedSignoff,
  ledgerBinding,
  sha256OfContent,
  signGovernedCommand,
} from './governed-command-signature.js';
import { signArtifactStatusByAna } from './ana-signed-artifact-act';

// Lazy pool access. Acquiring the pool at module load (`getPool()` at
// top level) throws "Database connection not available" when this module
// is imported in a context without a DB — which breaks any test whose
// import graph reaches command-executor (e.g. cortex-unified route smoke
// tests) before a request is ever made. This proxy defers getPool() to
// first property access, so import is side-effect-free and the pool is
// resolved on first real use. Runtime behavior is identical (same pool
// singleton); only the acquisition timing changes.
const pool = new Proxy({} as ReturnType<typeof getPool>, {
  get(_target, prop) {
    const real = getPool() as unknown as Record<string | symbol, unknown>;
    const value = real[prop];
    return typeof value === 'function' ? (value as (...a: unknown[]) => unknown).bind(real) : value;
  },
});

// ─────────────────────────────────────────────────────────────────────────────
// Backend service imports — wiring AnA to the full platform
// ─────────────────────────────────────────────────────────────────────────────
import { precedentEngine } from '../precedent-engine.js';
import { submissionTwinService } from '../submission-twin-service.js';
import { contradictionEngineService } from '../contradiction-engine-service.js';
import { crossJurisdictionalEngine } from '../cross-jurisdictional-intelligence.js';
import { getEndpointRecommenderService } from '../endpoint-recommender-service.js';
import { runRIMAssessment, type RIMContext } from '../intelligence/rim.js';
import // buildEvidenceChain, computeConfidence, EvidenceSource — reserved for evidence chain wiring
'../intelligence/evidence-confidence-model.js';
import { intelligentReportEngine } from '../intelligent-report-engine.js';
import { clinicalIntelligenceService } from '../clinical-intelligence-service.js';
import {
  module3BuildAll, module3BuildSection, module3MissingInputs,
  module3StaleSections, module3RefreshStale, module3Readiness,
  module3Contradictions, module3Lineage, module3ClassifySource,
  cmcStatus, ichCompliance, controlStrategy, variationsClassify,
} from './module3-command-handlers.js';
import { MDX_COMMAND_HANDLERS, MDX_COMMAND_METADATA } from './mdx-command-handlers';
import {
  MDX_COMMAND_HANDLERS_PHASE2,
  MDX_COMMAND_METADATA_PHASE2,
} from './mdx-command-handlers-phase2';
import {
  MDX_COMMAND_HANDLERS_PHASE3,
  MDX_COMMAND_METADATA_PHASE3,
} from './mdx-command-handlers-phase3';
import {
  PDEV_COMMAND_HANDLERS,
  PDEV_COMMAND_METADATA,
} from './pdev-command-handlers';
import { loadAnaToolPolicyStrict } from './mdx-tool-policy';
import {
  requiresPart11Signoff,
  requiresEsignature,
  validateSignoff,
  normalizedArtifactStatus,
  buildSignatureRequiredResult,
  buildHumanConfirmationRequiredResult,
  loadPart11EnforceStrict,
  type Part11Signoff,
} from './part11-governance';
import { authorizeCommand, isPrivacyAdmin, isProposeOnlyCommand } from './command-rbac';
import { carriesModelAuthoredText, sealProposalParams } from './proposal-seal';
import { isServedModelApprovedForHighRisk } from '../ai-governance/approved-models.js';
import { statedReasonOrNull } from '../../routes/governed-reason.js';
import { recordCommentPosted } from '../../routes/c2c/review-comment-record.js';
import { ANA_REVIEW_COMMENT_ROLE } from '../../../shared/constants/review-comment.js';
import {
  explainAuditRow,
  EXPLAIN_AUDIT_ROW_METADATA,
} from './mdx-explain-audit-row';
import {
  documentPreview,
  DOCUMENT_PREVIEW_METADATA,
} from './mdx-document-preview-tool';

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export interface CommandContext {
  userId: number;
  organizationId: number;
  activeProjectId?: number;
  userName?: string;
  userRole?: string;
  /**
   * Chat thread id. When present, the AnA-MDX governed-tool gate uses
   * it to look up pending actions stashed in mdx-pending-actions, so a
   * user can confirm a proposed action in a follow-up turn without
   * re-stating every parameter. Also written into audit details so an
   * auditor can pull the chat that produced any agent.ana.* mutation.
   */
  threadId?: string;
  /**
   * Chat message id of the user turn that produced the command. Written
   * into audit details for forensic linkage. The chat layer assigns
   * this when persisting the user message; if absent, audit linkage
   * falls back to threadId only.
   */
  chatMessageId?: string;
  /**
   * The model call whose response proposed this command: provider, model and
   * the gateway request id. Written into every agent mutation's audit row
   * (agentAuditDetails) so a Part 11 record traces to its ai.gateway_audit_log
   * row. Absent for a command a person typed.
   */
  servingModel?: { provider?: string | null; model?: string | null; requestId?: string | null } | null;
  /**
   * Per-tenant AnA tool policy. Stamped by `executeCommands` once per
   * dispatch from `organizations.settings.anaToolPolicy`. Read by the
   * shared gate in mdx-tool-policy.ts. Undefined = default = all tools
   * allowed.
   */
  anaToolPolicy?: {
    allow?: string[];
    deny?: string[];
  };
  /**
   * Whether Part 11 sign-off is enforced for this tenant. Stamped once per
   * dispatch from organizations.settings.anaPart11Enforce. When true, governed
   * record-altering commands fail closed unless `signoff` is present + valid.
   */
  part11Enforce?: boolean;
  /**
   * TRUE only when a human has confirmed THIS dispatch through the governed
   * sign-off flow. Assigned in exactly one place — the CommandContext literal
   * in server/routes/ana-ri/utility.ts, inside POST /api/ana-ri/governed-action,
   * which is reached only by a request the browser makes after
   * GovernedActionSignoff has collected the user's reason-for-change and, for
   * the e-signature tier, re-authenticated them server-side.
   *
   * Deliberately NOT settable from command params: params is the model's only
   * writable channel into a dispatch, so a field read from there could be
   * asserted by the model itself. Absence means "no human confirmed", which
   * blocks — so any future dispatch path that forgets to stamp it fails closed.
   */
  humanConfirmed?: boolean;
  /**
   * The verified Part 11 sign-off for THIS dispatch (reason-for-change +
   * server-verified electronic signature). Stamped by the route after it
   * verifies the user's re-authentication via the e-signature service.
   */
  signoff?: Part11Signoff;
  /**
   * Set true by `executeCommands` when the tenant's governance configuration
   * could not be RESOLVED for this dispatch — the tool-policy read or the
   * Part 11 flag read failed (DB error / no pool). It is NOT set when a read
   * succeeds and simply finds no restriction configured.
   *
   * Every mutation-capable command fails CLOSED while it is set
   * (command-rbac.ts `authorizeCommand`, and again in
   * `requireGovernedToolGate`). Read-only commands deliberately continue to
   * work: AnA degrades to read-only rather than to un-governed.
   */
  governanceUnavailable?: boolean;
}

export interface CommandResult {
  success: boolean;
  action: string;
  data?: Record<string, unknown>;
  message: string;
  error?: string;
  /** Optional UI hint: identifier of a modal/canvas the client may surface. */
  openModal?: string;
}

async function persistGovernedCommandArtifact(
  ctx: CommandContext,
  params: {
    projectId: number;
    artifactId?: number;
    sectionCode?: string;
    title: string;
    content: string;
    status?: string;
    documentType?: string;
    artifactClass: string;
    intendedAction: 'create' | 'update' | 'rollback';
    originSurface: string;
    metadata?: Record<string, unknown>;
    /** Runs inside the artifact write's transaction (see tagArtifact). */
    inTransaction?: ArtifactWriteHook;
  }
) {
  const qualityResult = validateArtifactQuality(params.content, params.documentType || 'general');
  const execution = await executeGovernedAnaOperation({
    evaluationInput: {
      context: {
        organizationId: String(ctx.organizationId),
        projectId: String(params.projectId),
        artifactId: params.artifactId ? String(params.artifactId) : undefined,
        actorId: String(ctx.userId),
        actorRole: ctx.userRole,
        intendedAction: params.intendedAction,
        documentType: params.documentType || 'general',
        sectionCode: params.sectionCode,
        ctdSection: params.sectionCode,
        originSurface: params.originSurface,
      },
      documentState: {
        hasContent: Boolean(params.content?.trim()),
        hasEvidence: /\[(KNOWN|INFERRED|MISSING)\]/.test(params.content || ''),
        hasBeenReviewed: false,
        hasApproval: false,
        hasPlacement: Boolean(params.sectionCode),
        placementValid: true,
        hasProvenance: true,
        unresolvedContradictionCount: 0,
        criticalContradictionCount: 0,
      },
    },
    artifactMutation: {
      projectId: params.projectId,
      organizationId: ctx.organizationId,
      artifactId: params.artifactId,
      documentType: params.documentType || 'general',
      artifactClass: params.artifactClass,
      sectionCode: params.sectionCode || 'unassigned',
      title: params.title,
      content: params.content,
      status: params.status || 'draft',
      source: 'AnA',
      intentLens: 'command',
      originSurface: params.originSurface,
      provenance: params.metadata || {},
      structureSections: [],
      qualityGate: {
        grade: qualityResult.grade,
        score: qualityResult.score,
        pass: qualityResult.pass,
        issues: qualityResult.issues,
      },
      versioningMode: params.artifactId ? 'update' : 'create',
    },
    inTransaction: params.inTransaction,
  });

  if (execution.persistenceStatus !== 'persisted' || !execution.artifactMutation) {
    throw new Error(`Governed persistence failed: ${execution.persistenceStatus}`);
  }

  return execution.artifactMutation;
}

// Privacy-admin authorization for the GDPR data-subject commands lives in
// command-rbac.ts (`isPrivacyAdmin`). It reads organization_users.role through
// the canonical RBAC service instead of the self-asserted `ctx.userRole`, which
// the chat bridge never populates — so the previous check evaluated `undefined`
// for every AnA-initiated cross-subject export/erase.

// ─────────────────────────────────────────────────────────────────────────────
// 1. PROJECT OPERATIONS
// ─────────────────────────────────────────────────────────────────────────────

/** Create a new project */
export async function createProject(
  ctx: CommandContext,
  params: {
    name: string;
    description?: string;
    submissionType?: string;
    therapeuticArea?: string;
    targetAgency?: string;
    phase?: string;
  }
): Promise<CommandResult> {
  try {
    const result = await pool.query(
      `INSERT INTO projects (organization_id, name, description, status, submission_type,
        therapeutic_area, created_by_id, created_at, updated_at)
       VALUES ($1, $2, $3, 'active', $4, $5, $6, NOW(), NOW())
       RETURNING id, name, status`,
      [
        ctx.organizationId,
        params.name,
        params.description || '',
        params.submissionType || null,
        params.therapeuticArea || null,
        ctx.userId,
      ]
    );
    const project = result.rows[0];
    const typeLabel = params.submissionType ? ` (${params.submissionType.toUpperCase()})` : '';
    const areaLabel = params.therapeuticArea ? ` in ${params.therapeuticArea}` : '';
    return {
      success: true,
      action: 'create_project',
      data: {
        projectId: project.id,
        name: project.name,
        status: project.status,
        submissionType: params.submissionType,
      },
      message: `Created project "${params.name}"${typeLabel}${areaLabel} — ID: ${project.id}, status: active.`,
    };
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : 'unknown error';
    return {
      success: false,
      action: 'create_project',
      message: `Failed to create project "${params.name}": ${errMsg}.`,
      error: errMsg,
    };
  }
}

/** List user's projects */
export async function listProjects(ctx: CommandContext): Promise<CommandResult> {
  try {
    const result = await pool.query(
      `SELECT id, name, status, submission_type, therapeutic_area, progress,
              created_at, updated_at
       FROM projects
       WHERE organization_id = $1
       ORDER BY updated_at DESC
       LIMIT 50`,
      [ctx.organizationId]
    );
    return {
      success: true,
      action: 'list_projects',
      data: { projects: result.rows, count: result.rows.length },
      message: `Found ${result.rows.length} project(s).`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'list_projects',
      message: 'Failed to list projects.',
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * Update project metadata.
 *
 * Signature is (ctx, params) — the contract the command dispatcher actually
 * uses (`handler(ctx, cmd.params)`), matching the sibling update_task handler.
 * The previous signature was (ctx, projectId, updates), which no call site ever
 * satisfied: dispatch passed the whole params object as `projectId` and left
 * `updates` undefined, so Object.entries(updates) threw on EVERY invocation and
 * update_project could never succeed. A cast in COMMAND_HANDLERS hid the
 * mismatch from the compiler rather than fixing it.
 */
export async function updateProject(
  ctx: CommandContext,
  params: { projectId?: number; updates?: Record<string, unknown> } & Record<string, unknown>
): Promise<CommandResult> {
  const projectId = Number(params?.projectId ?? (params as Record<string, unknown>)?.project_id);
  try {
    if (!Number.isInteger(projectId) || projectId <= 0) {
      return {
        success: false,
        action: 'update_project',
        message: 'A valid numeric projectId is required.',
      };
    }

    // Canonical shape is { projectId, updates: {...} } (as update_task uses).
    // Tolerate a flat { projectId, ...fields } shape by treating any non-control
    // key as an update field, so a slightly different tool emission still works.
    const updates: Record<string, unknown> =
      params.updates && typeof params.updates === 'object'
        ? (params.updates as Record<string, unknown>)
        : Object.fromEntries(
            Object.entries(params ?? {}).filter(
              ([k]) => k !== 'projectId' && k !== 'project_id' && k !== 'updates'
            )
          );

    const allowedFields = [
      'name',
      'description',
      'status',
      'submission_type',
      'therapeutic_area',
      'phase',
      'priority',
      'risk_level',
    ];
    const setClauses: string[] = [];
    const values: unknown[] = [projectId, ctx.organizationId];
    let paramIdx = 3;

    for (const [key, value] of Object.entries(updates)) {
      const snakeKey = key.replace(/([A-Z])/g, '_$1').toLowerCase();
      if (allowedFields.includes(snakeKey)) {
        setClauses.push(`${snakeKey} = $${paramIdx}`);
        values.push(value);
        paramIdx++;
      }
    }

    if (setClauses.length === 0) {
      return { success: false, action: 'update_project', message: 'No valid fields to update.' };
    }

    setClauses.push('updated_at = NOW()');
    const setSql = setClauses.join(', ');
    const result = await pool.query(
      `UPDATE projects SET ${setSql} WHERE id = $1 AND organization_id = $2`,
      values
    );
    // Do not report success when the tenant-scoped WHERE matched no row — the
    // project does not exist or belongs to another organization. Reporting
    // "updated" for a write that changed nothing is a false success.
    if ((result.rowCount ?? 0) === 0) {
      return {
        success: false,
        action: 'update_project',
        message: `Project ${projectId} was not found in this organization; nothing was updated.`,
      };
    }
    const fieldList = Object.keys(updates).join(', ');
    return {
      success: true,
      action: 'update_project',
      data: { projectId, updated: Object.keys(updates) },
      message: `Project ${projectId} updated: ${fieldList}.`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'update_project',
      message: `Failed to update project ${projectId}: ${
        err instanceof Error ? err.message : 'unknown error'
      }.`,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. DOCUMENT / ARTIFACT OPERATIONS
// ─────────────────────────────────────────────────────────────────────────────

/** Create a new artifact (document) in a project */
export async function createArtifact(
  ctx: CommandContext,
  params: {
    projectId: number;
    title: string;
    content: string;
    type?: string;
    ctdSection?: string;
    status?: string;
    source?: string;
    metadata?: Record<string, unknown>;
  }
): Promise<CommandResult> {
  try {
    // Quality gate — reject garbage before persisting
    const qualityResult = validateArtifactQuality(params.content, params.type || 'general');
    if (!qualityResult.pass) {
      logGeneration({
        timestamp: new Date().toISOString(),
        route: 'ana-ri/command',
        action: 'create_artifact',
        projectId: params.projectId,
        organizationId: ctx.organizationId,
        userId: ctx.userId,
        artifactCreated: false,
        anaRiOrchestrated: true,
        qualityGrade: qualityResult.grade,
      });
      return {
        success: false,
        action: 'create_artifact',
        message: `Quality gate rejected "${params.title}": ${qualityResult.issues.join('; ')}.`,
        error: `Quality grade: ${qualityResult.grade}`,
      };
    }

    const execution = await executeGovernedAnaOperation({
      evaluationInput: {
        context: {
          organizationId: String(ctx.organizationId),
          projectId: String(params.projectId),
          actorId: String(ctx.userId),
          actorRole: ctx.userRole,
          intendedAction: 'create',
          documentType: params.type || 'general',
          sectionCode: params.ctdSection,
          ctdSection: params.ctdSection,
          originSurface: 'ana-ri-command',
        },
        documentState: {
          hasContent: Boolean(params.content?.trim()),
          hasEvidence: /\\[(KNOWN|INFERRED|MISSING)\\]/.test(params.content || ''),
          hasBeenReviewed: false,
          hasApproval: false,
          hasPlacement: Boolean(params.ctdSection),
          placementValid: true,
          hasProvenance: true,
          unresolvedContradictionCount: 0,
          criticalContradictionCount: 0,
        },
      },
      artifactMutation: {
        projectId: params.projectId,
        organizationId: ctx.organizationId,
        documentType: params.type || 'general',
        artifactClass: 'ana_command_artifact',
        sectionCode: params.ctdSection || 'unassigned',
        title: params.title,
        content: params.content,
        status: params.status || 'draft',
        source: 'AnA',
        intentLens: 'command',
        originSurface: 'ana-ri-command',
        provenance: {
          ...params.metadata,
          createdVia: 'ana_command',
          createdBy: ctx.userName || ctx.userId,
        },
        structureSections: [],
        qualityGate: {
          grade: qualityResult.grade,
          score: qualityResult.score,
          pass: qualityResult.pass,
          issues: qualityResult.issues,
        },
        versioningMode: 'create',
      },
    });

    if (execution.persistenceStatus !== 'persisted' || !execution.artifactMutation) {
      return {
        success: false,
        action: 'create_artifact',
        message: execution.persistenceRefusal?.message ?? `Governed persistence failed for "${params.title}"`,
        error: execution.persistenceRefusal?.code ?? execution.persistenceStatus,
      };
    }

    logGeneration({
      timestamp: new Date().toISOString(),
      route: 'ana-ri/command',
      action: 'create_artifact',
      projectId: params.projectId,
      organizationId: ctx.organizationId,
      userId: ctx.userId,
      artifactCreated: true,
      artifactId: execution.artifactMutation.artifactId,
      anaRiOrchestrated: true,
    });

    const sectionLabel =
      params.ctdSection && params.ctdSection !== 'unassigned'
        ? ` in section ${params.ctdSection}`
        : '';
    const statusLabel = params.status || 'draft';
    return {
      success: true,
      action: 'create_artifact',
      data: {
        artifactId: execution.artifactMutation.artifactId,
        isNew: execution.artifactMutation.isNew,
        sectionCode: execution.artifactMutation.sectionCode,
        title: params.title,
      },
      message: `Created "${params.title}"${sectionLabel} — ID: ${execution.artifactMutation.artifactId}, status: ${statusLabel}.`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'create_artifact',
      message: `Failed to create artifact "${params.title}": ${
        err instanceof Error ? err.message : 'unknown error'
      }.`,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/** Update artifact content (creates a new version) */
export async function updateArtifact(
  ctx: CommandContext,
  params: {
    projectId: number;
    artifactId: number;
    content: string;
    title?: string;
    changeDescription?: string;
  }
): Promise<CommandResult> {
  try {
    // Document-state guard: check if artifact is locked or approved before mutation
    const existing = await pool.query(
      `SELECT artifact_id, title, status, ctd_section, version
       FROM concept2cure_artifacts
       WHERE artifact_id = $1 AND project_id = $2 AND organization_id = $3`,
      [params.artifactId, params.projectId, ctx.organizationId]
    );

    if (existing.rows.length === 0) {
      return {
        success: false,
        action: 'update_artifact',
        message: `Artifact ${params.artifactId} not found in project ${params.projectId}.`,
      };
    }

    const current = existing.rows[0];
    if (current.status === 'locked') {
      return {
        success: false,
        action: 'update_artifact',
        message: `Cannot update "${current.title}" — document is locked. Create a new version or change status to draft first.`,
        data: { artifactId: params.artifactId, currentStatus: 'locked', title: current.title },
      };
    }
    if (current.status === 'approved') {
      return {
        success: false,
        action: 'update_artifact',
        message: `Cannot update "${current.title}" — document is approved. Editing an approved document requires changing its status back to draft or review first, which will trigger re-review.`,
        data: { artifactId: params.artifactId, currentStatus: 'approved', title: current.title },
      };
    }

    const result = await persistGovernedCommandArtifact(ctx, {
      projectId: params.projectId,
      artifactId: params.artifactId,
      sectionCode: current.ctd_section || undefined,
      title: params.title || current.title || '',
      content: params.content,
      status: 'draft',
      documentType: 'general',
      artifactClass: 'ana_command_artifact_update',
      intendedAction: 'update',
      originSurface: 'ana-ri-command',
      metadata: {
        updatedVia: 'ana_command',
        changeDescription: params.changeDescription || 'Updated by AnA RI',
      },
    });

    const sectionLabel = current.ctd_section ? ` in section ${current.ctd_section}` : '';
    const newVersion = result.versionId ? ` — version ${result.versionId}` : '';
    return {
      success: true,
      action: 'update_artifact',
      data: {
        artifactId: result.artifactId,
        versionId: result.versionId,
        title: current.title,
        ctdSection: current.ctd_section,
      },
      message: `Updated "${current.title}"${sectionLabel}${newVersion}. ${
        params.changeDescription || 'Content revised by AnA.'
      }`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'update_artifact',
      message: `Failed to update artifact ${params.artifactId}: ${
        err instanceof Error ? err.message : 'unknown error'
      }.`,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/** Update artifact status with lifecycle transition guards */
export async function updateArtifactStatus(
  ctx: CommandContext,
  params: {
    projectId: number;
    artifactId: number;
    status: 'draft' | 'review' | 'approved' | 'locked';
  }
): Promise<CommandResult> {
  try {
    // Approving and locking are electronic signatures (2026-10-01, D5): the
    // status route's act, with its rules, through the governed-action sign-off
    // (ana-signed-artifact-act.ts). They were the reason tier here, and wrote
    // the status with no signature, no version and no snapshot.
    const target = normalizedArtifactStatus(params.status);
    if (target === 'approved' || target === 'locked') {
      return await signArtifactStatusByAna(ctx, { ...params, status: target });
    }
    // Anything else unsigned is draft or review, by name. 'Approved' or 'LOCKED'
    // used to be the reason tier and was written raw, where some readers took
    // it as finalized (review of dacc2ff84).
    if (target !== 'draft' && target !== 'review') {
      return {
        success: false,
        action: 'update_artifact_status',
        message:
          `"${String(params.status)}" is not a status this command moves an artifact to: draft or review, ` +
          'or approved and locked as an electronic signature. Nothing was changed.',
      };
    }

    // Load current artifact to validate transition
    const existing = await pool.query(
      `SELECT artifact_id, title, status, ctd_section,
              version, approved_version_id, published_version_id
       FROM concept2cure_artifacts
       WHERE artifact_id = $1 AND project_id = $2 AND organization_id = $3`,
      [params.artifactId, params.projectId, ctx.organizationId]
    );

    if (existing.rows.length === 0) {
      return {
        success: false,
        action: 'update_artifact_status',
        message: `Artifact ${params.artifactId} not found.`,
      };
    }

    const current = existing.rows[0];
    const fromStatus = current.status;
    const toStatus = target;

    // Guard: locked documents cannot be status-changed without explicit unlock
    if (fromStatus === 'locked' && toStatus !== 'draft') {
      return {
        success: false,
        action: 'update_artifact_status',
        message: `"${current.title}" is locked. Locked documents can only be unlocked to draft status — this will trigger full re-review.`,
        data: { artifactId: params.artifactId, currentStatus: 'locked', requestedStatus: toStatus },
      };
    }

    // Guard: warn about approved → draft regression (but allow it)
    const isRegression =
      fromStatus === 'approved' && (toStatus === 'draft' || toStatus === 'review');

    // Draft and review only, here (approve and lock returned above). Leaving
    // approved/locked clears any recorded version in this same write (the
    // trigger in migrations/20260923b_artifact_approval_follows_status.sql), so
    // an approval revoked earlier is not resurrected.
    await pool.query(
      `UPDATE concept2cure_artifacts
       SET status = $4, updated_at = NOW()
       WHERE artifact_id = $1 AND project_id = $2 AND organization_id = $3`,
      [params.artifactId, params.projectId, ctx.organizationId, toStatus]
    );

    const transitionLabel = `${fromStatus} → ${toStatus}`;
    const sectionLabel = current.ctd_section ? ` (section ${current.ctd_section})` : '';
    const regressionWarning = isRegression
      ? ' ⚠ This reverses approval and will require re-review before the document can be approved again.'
      : '';

    return {
      success: true,
      action: 'update_artifact_status',
      data: {
        artifactId: params.artifactId,
        previousStatus: fromStatus,
        status: toStatus,
        title: current.title,
        isRegression,
      },
      message: `"${current.title}"${sectionLabel} status changed: ${transitionLabel}.${regressionWarning}`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'update_artifact_status',
      message: `Failed to update status for artifact ${params.artifactId}: ${
        err instanceof Error ? err.message : 'unknown error'
      }.`,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * The artifact a placement signs, locked in the signing transaction. Scoped by
 * artifact, project AND organization: an artifact that is not this caller's
 * is not found, and nothing is written.
 */
async function lockArtifactForSigning(
  client: PoolClient,
  ctx: CommandContext,
  params: { projectId: number; artifactId: number | string }
): Promise<{ artifact_id: string; version: number; content: string; title: string | null } | null> {
  const found = await client.query(
    `SELECT artifact_id, version, content, title
       FROM concept2cure_artifacts
      WHERE artifact_id = $1 AND project_id = $2 AND organization_id = $3
      FOR UPDATE`,
    [params.artifactId, params.projectId, ctx.organizationId]
  );
  return found.rows[0] ?? null;
}

/**
 * Place artifact in CTD dossier section.
 *
 * An e-signature-tier command (PART11_ESIGN_COMMANDS): the placement and its
 * electronic signature commit in ONE transaction, or neither does. The signer
 * signs "this content, at this version, placed here" — a content binding over
 * the artifact as it stands under the row lock (2026-09-28; until then a person
 * re-authenticated for this command and no signature was recorded).
 */
export async function placeInDossier(
  ctx: CommandContext,
  params: {
    projectId: number;
    artifactId: number;
    ctdSection: string;
    dossierModule?: string;
  }
): Promise<CommandResult> {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const artifact = await lockArtifactForSigning(client, ctx, params);
    // Fail closed: don't report a placement that didn't happen (artifact not in
    // this project/org). AnA must never confirm work it didn't perform.
    if (!artifact) {
      await client.query('ROLLBACK');
      return {
        success: false,
        action: 'place_in_dossier',
        message: `Artifact ${params.artifactId} was not found in this project, so nothing was placed.`,
      };
    }
    await client.query(
      `UPDATE concept2cure_artifacts
       SET ctd_section = $4, updated_at = NOW()
       WHERE artifact_id = $1 AND project_id = $2 AND organization_id = $3`,
      [artifact.artifact_id, params.projectId, ctx.organizationId, params.ctdSection]
    );
    const binding = artifactVersionContentBinding({
      artifactId: artifact.artifact_id,
      version: Number(artifact.version),
      content: artifact.content,
      ctdSection: params.ctdSection,
    });
    const { signatureId } = await signGovernedCommand(client, ctx, {
      command: 'place_in_dossier',
      target: `artifact:${artifact.artifact_id}`,
      payload: {
        projectId: params.projectId,
        artifactId: artifact.artifact_id,
        version: Number(artifact.version),
        ctdSection: params.ctdSection,
        contentSha256: binding.contentSha256,
      },
      binding,
      extraManifest: { version: Number(artifact.version), ctdSection: params.ctdSection, contentSha256: binding.contentSha256 },
    });
    await client.query('COMMIT');

    const artTitle = artifact.title || `Artifact ${params.artifactId}`;
    const moduleLabel = params.dossierModule ? ` (Module ${params.dossierModule})` : '';
    return {
      success: true,
      action: 'place_in_dossier',
      data: { artifactId: params.artifactId, ctdSection: params.ctdSection, title: artTitle, signatureId },
      message: `Placed "${artTitle}" in CTD section ${params.ctdSection}${moduleLabel}.`,
    };
  } catch (err: unknown) {
    await client.query('ROLLBACK').catch(() => undefined);
    return {
      success: false,
      action: 'place_in_dossier',
      message: `Failed to place artifact ${params.artifactId} in section ${params.ctdSection}: ${
        err instanceof Error ? err.message : 'unknown error'
      }.`,
      error: err instanceof Error ? err.message : String(err),
    };
  } finally {
    client.release();
  }
}

/** List artifacts in a project */
export async function listArtifacts(
  ctx: CommandContext,
  projectId: number,
  filters?: { status?: string; ctdSection?: string }
): Promise<CommandResult> {
  try {
    let query = `SELECT artifact_id, title, status, ctd_section, version, type, created_at, updated_at
                 FROM concept2cure_artifacts
                 WHERE project_id = $1 AND organization_id = $2`;
    const values: unknown[] = [projectId, ctx.organizationId];
    let paramIdx = 3;

    if (filters?.status) {
      query += ` AND status = $${paramIdx}`;
      values.push(filters.status);
      paramIdx++;
    }
    if (filters?.ctdSection) {
      query += ` AND ctd_section = $${paramIdx}`;
      values.push(filters.ctdSection);
      paramIdx++;
    }

    query += ' ORDER BY updated_at DESC LIMIT 100';
    const result = await pool.query(query, values);

    return {
      success: true,
      action: 'list_artifacts',
      data: { artifacts: result.rows, count: result.rows.length },
      message: `Found ${result.rows.length} artifact(s) in project ${projectId}.`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'list_artifacts',
      message: 'Failed to list artifacts.',
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. TASK MANAGEMENT
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Write to the canonical regulated task table and record its lineage row in ONE
 * transaction: both commit, or neither does.
 *
 * `write` performs the board write on `client` and returns the lineage row to
 * record, or null when the write changed nothing that needs one. Until
 * 2026-09-24 AnA wrote the board row on the pool and the lineage row afterwards
 * in its own best-effort transaction, so a lineage failure left a governed
 * change on the board with no §11.10(e) record of it. The HTTP task routes
 * already commit the row with the write (`auditTaskActionInTx`).
 *
 * Best-effort as a whole, as the mirror always was: a failure is logged and
 * reported to the caller (false), and the project_tasks write that preceded it
 * stands. What it can no longer do is land half.
 */
async function boardWriteWithLineage(
  label: string,
  write: (client: PoolClient) => Promise<AuditTaskActionParams | BoardWriteRecord | null>,
): Promise<boolean> {
  let client: PoolClient | undefined;
  let notices: TaskEventNotice[] = [];
  try {
    client = (await pool.connect()) as PoolClient;
    await client.query('BEGIN');
    const written = await write(client);
    const record: BoardWriteRecord | null =
      written === null ? null : 'lineage' in written ? written : { lineage: [written] };
    if (record) {
      const { auditTaskAction, TaskAuditNotRecordedError } = await import('../tasking/task-audit.js');
      // In order: the change's own row, then the rows of what it caused.
      for (const row of record.lineage) {
        const outcome = await auditTaskAction(row, client);
        if (!outcome.recorded) throw new TaskAuditNotRecordedError(outcome.reason);
      }
      notices = record.notices ?? [];
    }
    await client.query('COMMIT');
  } catch (err) {
    await client?.query('ROLLBACK').catch(() => undefined);
    console.warn(`[ana-ri] ${label} failed (non-fatal):`, err instanceof Error ? err.message : err);
    return false;
  } finally {
    client?.release();
  }
  // Only for what committed.
  if (notices.length > 0) {
    const { notifyTaskEvent } = await import('../tasking/task-side-effects.js');
    for (const notice of notices) notifyTaskEvent(notice);
  }
  return true;
}

/**
 * The lineage row for a task write AnA carried out. Its reason is the one the
 * person stated through a verified sign-off (`ctx.signoff`, stamped only by
 * POST /api/ana-ri/governed-action), or none — task-audit records null. Both
 * task commands are the confirm tier (part11-governance.ts governedTierOf): the
 * person says yes and is asked for no reason, and a `reason` the model wrote
 * into params is not theirs. What AnA did is the row's `summary`. Until
 * 2026-10-01 these rows recorded "Task created by AnA and mirrored to the
 * canonical task board" / "Task status changed by AnA" as the reason (D5).
 */
function anaTaskLineage(ctx: CommandContext, event: AnaTaskEvent): AuditTaskActionParams {
  return { orgId: ctx.organizationId, userId: ctx.userId, reason: ctx.signoff?.reasonForChange, ...event };
}
type AnaTaskEvent = Pick<AuditTaskActionParams, 'command' | 'taskId' | 'payload' | 'summary'>;

/** What a board write records when it caused more than its own change: its own
 *  row first, then one per record it moved (a completion's unblocked
 *  dependents), and the notices to send once all of it has committed. */
interface BoardWriteRecord {
  lineage: AuditTaskActionParams[];
  notices?: TaskEventNotice[];
}

/**
 * Mirror an AnA-created project task into the canonical org board
 * (unified_tasks) so a task created in chat is visible on the Task Board —
 * previously AnA wrote project_tasks alone and the board read unified_tasks,
 * so "create a task" produced work nothing surfaced (assessment finding 3).
 * Best-effort: a mirror failure never fails the create, and the caller is told
 * (false) so it does not report a board entry that is not there. The
 * unified-work view excludes sourceEntityType='project_task' rows so the task
 * is never counted twice; the mirror carries a deterministic task_id so re-runs
 * are idempotent.
 */
async function mirrorProjectTaskToUnified(
  ctx: CommandContext,
  projectTaskId: number,
  params: {
    projectId: number;
    title: string;
    description?: string;
    assigneeId?: number;
    priority?: string;
    dueDate?: string;
    moduleType?: string;
  }
): Promise<boolean> {
  const mirroredTaskId = `TASK-PT-${ctx.organizationId}-${projectTaskId}`;
  let inserted = false;
  const onBoard = await boardWriteWithLineage('unified_tasks mirror', async (client) => {
    const result = await client.query(
      `INSERT INTO unified_tasks
         (task_id, organization_id, project_id, module_type, title, description,
          assignee_id, priority, due_date, status, source_entity_type,
          source_entity_id, created_by_id, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'pending', 'project_task', $10, $11, NOW(), NOW())
       ON CONFLICT (task_id) DO NOTHING
       RETURNING task_id`,
      [
        mirroredTaskId,
        ctx.organizationId,
        params.projectId,
        params.moduleType || 'general',
        params.title,
        params.description || '',
        params.assigneeId || null,
        params.priority || 'medium',
        params.dueDate || null,
        String(projectTaskId),
        ctx.userId,
      ]
    );
    inserted = Boolean(result.rowCount);
    // A row landing in the canonical regulated task table is a governed
    // create, whoever wrote it: record the same `task.create` lineage the
    // tasking routes record. Nothing on a conflict (an idempotent re-run wrote
    // nothing).
    if (!inserted) return null;
    return anaTaskLineage(ctx, {
      command: 'task.create',
      taskId: mirroredTaskId,
      payload: {
        moduleType: params.moduleType || 'general',
        title: params.title,
        priority: params.priority || 'medium',
        status: 'pending',
        sourceEntityType: 'project_task',
        sourceEntityId: String(projectTaskId),
      },
      summary: 'Task created by AnA and mirrored to the canonical task board',
    });
  });
  // Tell the assignee only about a board row that committed.
  if (onBoard && inserted && params.assigneeId && params.assigneeId !== ctx.userId) {
    try {
      const { notifyTaskEvent } = await import('../tasking/task-side-effects.js');
      notifyTaskEvent({
        organizationId: ctx.organizationId,
        recipientUserId: params.assigneeId,
        category: 'task_assigned',
        title: `Task assigned: ${params.title}`,
        body: params.description || null,
        taskId: mirroredTaskId,
      });
    } catch (err) {
      console.warn('[ana-ri] task assignment notice failed (non-fatal):', err instanceof Error ? err.message : err);
    }
  }
  return onBoard;
}

/** project_tasks status → unified_tasks status, for the mirror. */
function mirrorStatus(raw: unknown): string | null {
  const v = String(raw ?? '').trim().toLowerCase();
  if (!v) return null;
  if (v === 'todo' || v === 'pending') return 'pending';
  if (v === 'in-progress' || v === 'in_progress') return 'in-progress';
  if (v === 'review') return 'review';
  if (v === 'done' || v === 'completed') return 'completed';
  if (v === 'blocked') return 'blocked';
  if (v === 'cancelled') return 'cancelled';
  return null;
}

/** Create a task in a project */
export async function createTask(
  ctx: CommandContext,
  params: {
    projectId: number;
    title: string;
    description?: string;
    assigneeId?: number;
    priority?: 'low' | 'medium' | 'high' | 'urgent';
    dueDate?: string;
    moduleType?: string;
  }
): Promise<CommandResult> {
  try {
    const result = await pool.query(
      `INSERT INTO project_tasks
         (project_id, organization_id, name, description, assignee_id,
          priority, due_date, module_type, status, created_by_id, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'todo', $9, NOW(), NOW())
       RETURNING id, name, status, priority`,
      [
        params.projectId,
        ctx.organizationId,
        params.title,
        params.description || '',
        params.assigneeId || null,
        params.priority || 'medium',
        params.dueDate || null,
        params.moduleType || null,
        ctx.userId,
      ]
    );
    const task = result.rows[0];
    const onTaskBoard = await mirrorProjectTaskToUnified(ctx, task.id, params);
    const priorityLabel =
      params.priority && params.priority !== 'medium' ? `, priority: ${params.priority}` : '';
    const dueLabel = params.dueDate ? `, due: ${params.dueDate}` : '';
    const boardNote = onTaskBoard
      ? ''
      : ' It is not on the task board: the board entry and its audit record could not be written.';
    return {
      success: true,
      action: 'create_task',
      data: { taskId: task.id, name: task.name, priority: task.priority, status: task.status, onTaskBoard },
      message: `Created task "${params.title}" — ID: ${task.id}${priorityLabel}${dueLabel}.${boardNote}`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'create_task',
      message: `Failed to create task "${params.title}": ${
        err instanceof Error ? err.message : 'unknown error'
      }.`,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/** Update a task */
export async function updateTask(
  ctx: CommandContext,
  params: {
    projectId: number;
    taskId: number;
    updates: Record<string, unknown>;
  }
): Promise<CommandResult> {
  try {
    const allowedFields = [
      'name',
      'description',
      'status',
      'priority',
      'assignee_id',
      'due_date',
      'module_type',
    ];
    const setClauses: string[] = [];
    const values: unknown[] = [params.taskId, params.projectId, ctx.organizationId];
    let paramIdx = 4;

    for (const [key, value] of Object.entries(params.updates)) {
      const snakeKey = key.replace(/([A-Z])/g, '_$1').toLowerCase();
      if (allowedFields.includes(snakeKey)) {
        setClauses.push(`${snakeKey} = $${paramIdx}`);
        values.push(value);
        paramIdx++;
      }
    }

    if (setClauses.length === 0) {
      return { success: false, action: 'update_task', message: 'No valid fields to update.' };
    }

    // Read the canonical mirror BEFORE writing anything. The status domain has
    // to be enforced ahead of the project_tasks write, not after it: rejecting
    // afterwards would leave project_tasks already mutated while telling the
    // caller nothing happened, and the two tables would disagree.
    const mirroredTaskId = `TASK-PT-${ctx.organizationId}-${params.taskId}`;
    const requestedStatus = mirrorStatus((params.updates as Record<string, unknown>).status);
    let mirrorFrom: string | null = null;
    /** The approval state of the mirror row, so the e-signature gate can be
     *  applied here on the same terms the HTTP route applies it. */
    let mirrorApproval: {
      approvalRequired: boolean | null;
      approvalStatus: string | null;
      approvers: unknown;
    } | null = null;
    try {
      const currentRes = await pool.query(
        `SELECT status, approval_required, approval_status, approvers
           FROM unified_tasks
         WHERE source_entity_type = 'project_task'
           AND source_entity_id = $1
           AND organization_id = $2
           AND deleted_at IS NULL`,
        [String(params.taskId), ctx.organizationId]
      );
      mirrorFrom = currentRes.rows[0] ? String(currentRes.rows[0].status) : null;
      mirrorApproval = currentRes.rows[0]
        ? {
            approvalRequired: currentRes.rows[0].approval_required as boolean | null,
            approvalStatus: currentRes.rows[0].approval_status as string | null,
            approvers: currentRes.rows[0].approvers,
          }
        : null;
    } catch (err) {
      // No mirror row readable (unprovisioned column, transient): fall through
      // and treat this as an unmirrored task, exactly as before.
      console.warn(
        '[ana-ri] unified_tasks mirror read failed (non-fatal):',
        err instanceof Error ? err.message : err
      );
    }

    // Same domain rules as the routes: AnA must not drive a transition the HTTP
    // path answers with a 409 (e.g. pending → completed).
    if (mirrorFrom && requestedStatus && requestedStatus !== mirrorFrom) {
      const { isLegalTransition } = await import('../tasking/task-state-machine.js');
      if (!isLegalTransition(mirrorFrom, requestedStatus)) {
        return {
          success: false,
          action: 'update_task',
          message: `A task in "${mirrorFrom}" cannot move to "${requestedStatus}".`,
        };
      }
    }

    // ── §11.50 e-signature gate ────────────────────────────────────────────
    // The HTTP route answers 428 ESIGN_REQUIRED when an approval-gated task is
    // completed without a PIN-verified signature (taskManagement.routes.ts).
    // This path completed the very same canonical row and never consulted it,
    // so asking AnA to "mark it done" cleared a gate that the button in front
    // of the user could not clear. That is not an AnA feature — it is the
    // control being routed around, and the signature is exactly the thing that
    // cannot be delegated to an agent: §11.200 requires it to attest that a
    // PERSON decided.
    //
    // AnA cannot collect a PIN, so there is no signature to verify here and
    // nothing to add to the ceremony. The only correct answer is to refuse and
    // hand the user back to the surface that CAN run it. Checked before any
    // write, so a refusal never leaves project_tasks already mutated.
    if (
      requestedStatus === 'completed' &&
      mirrorApproval?.approvalRequired === true &&
      mirrorApproval.approvalStatus !== 'approved'
    ) {
      return {
        success: false,
        action: 'update_task',
        message:
          `Task ${params.taskId} is approval-gated, so completing it needs an electronic ` +
          `signature — your signing PIN, the meaning of the signature, and a reason. ` +
          `I can't sign on your behalf. Open the task on the task board and complete it ` +
          `there; the signature has to be yours.`,
      };
    }

    setClauses.push('updated_at = NOW()');
    const setSql = setClauses.join(', ');
    const result = await pool.query(
      `UPDATE project_tasks SET ${setSql}
       WHERE id = $1 AND project_id = $2 AND organization_id = $3`,
      values
    );
    // Same false-success guard as update_project: a tenant-scoped UPDATE that
    // matched no row (wrong task/project or another org's) must not report success.
    if ((result.rowCount ?? 0) === 0) {
      return {
        success: false,
        action: 'update_task',
        message: `Task ${params.taskId} was not found for this project/organization; nothing was updated.`,
      };
    }

    // Keep the canonical-board mirror in step (best-effort; see createTask).
    //
    // A status change here mutates the canonical regulated table, so it carries
    // the same obligations the HTTP routes carry — the create mirror above
    // already states the rule ("a row landing in the canonical regulated task
    // table is a governed create, whoever wrote it"), and this path was the
    // half that had not been brought up to it: no ledger entry, no state
    // machine, no completion stamp, no unblock cascade, and no tombstone guard.
    // The board write and its `task.transition` row commit together
    // (boardWriteWithLineage), so the board never moves unrecorded.
    const u = params.updates as Record<string, unknown>;
    const newStatus = requestedStatus;
    /** null: no board change was attempted; false: attempted and not written. */
    let boardUpdated: boolean | null = null;
    let transitioned = false;

    // Only mirror onto a row we actually read above. `deleted_at IS NULL` is
    // repeated on the write so an archived Part 11 tombstone is never
    // silently re-written.
    if (mirrorFrom !== null) {
      const mirrorSets: string[] = [];
      const mirrorVals: unknown[] = [String(params.taskId), ctx.organizationId];
      let mi = 3;
      if (newStatus) { mirrorSets.push(`status = $${mi++}`); mirrorVals.push(newStatus); }
      if (typeof u.name === 'string' && u.name) { mirrorSets.push(`title = $${mi++}`); mirrorVals.push(u.name); }
      if (typeof u.priority === 'string' && u.priority) { mirrorSets.push(`priority = $${mi++}`); mirrorVals.push(u.priority); }
      if (newStatus === 'completed') {
        mirrorSets.push('completed_at = NOW()', 'progress = 100', 'completion_percentage = 100');
      }
      if (mirrorSets.length) {
        mirrorSets.push('updated_at = NOW()');
        boardUpdated = await boardWriteWithLineage('unified_tasks mirror update', async (client) => {
          const mirrored = await client.query(
            `UPDATE unified_tasks SET ${mirrorSets.join(', ')}
             WHERE source_entity_type = 'project_task'
               AND source_entity_id = $1
               AND organization_id = $2
               AND deleted_at IS NULL`,
            mirrorVals
          );
          // Governed lineage only for a status change that actually landed.
          transitioned = Boolean(mirrored.rowCount) && Boolean(newStatus) && newStatus !== mirrorFrom;
          if (!transitioned) return null;
          const own = anaTaskLineage(ctx, {
            command: 'task.transition',
            taskId: mirroredTaskId,
            payload: { from: mirrorFrom, to: newStatus },
            summary: 'Task status changed by AnA',
          });
          if (newStatus !== 'completed') return own;
          // Completing a task wakes its dependents on every write path — here
          // on this transaction, locking them after the completed row and
          // before any ledger row, so the completion, the dependents' moves and
          // every row recording them commit together or not at all.
          const { cascadeUnblockOnCompletionOnClient } = await import('../tasking/task-side-effects.js');
          const cascade = await cascadeUnblockOnCompletionOnClient(ctx.organizationId, mirroredTaskId, {
            client,
            actorUserId: ctx.userId,
          });
          return { lineage: [own, ...cascade.ledger], notices: cascade.notices };
        });
      }
    }

    const boardNote =
      boardUpdated === false
        ? ' The task board still shows the previous state: the board change and its audit record could not be written.'
        : '';
    return {
      success: true,
      action: 'update_task',
      data: { taskId: params.taskId, updated: Object.keys(params.updates), boardUpdated },
      message: `Task ${params.taskId} updated.${boardNote}`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'update_task',
      message: 'Failed to update task.',
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/** List tasks in a project */
export async function listTasks(
  ctx: CommandContext,
  projectId: number,
  filters?: { status?: string; priority?: string; assigneeId?: number }
): Promise<CommandResult> {
  try {
    let query = `SELECT id, name, description, status, priority, assignee_id, due_date,
                        module_type, created_at, updated_at
                 FROM project_tasks
                 WHERE project_id = $1 AND organization_id = $2`;
    const values: unknown[] = [projectId, ctx.organizationId];
    let paramIdx = 3;

    if (filters?.status) {
      query += ` AND status = $${paramIdx}`;
      values.push(filters.status);
      paramIdx++;
    }
    if (filters?.priority) {
      query += ` AND priority = $${paramIdx}`;
      values.push(filters.priority);
      paramIdx++;
    }
    if (filters?.assigneeId) {
      query += ` AND assignee_id = $${paramIdx}`;
      values.push(filters.assigneeId);
      paramIdx++;
    }

    query +=
      " ORDER BY CASE priority WHEN 'urgent' THEN 0 WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'medium' THEN 3 ELSE 4 END, due_date ASC NULLS LAST LIMIT 100";
    const result = await pool.query(query, values);

    return {
      success: true,
      action: 'list_tasks',
      data: { tasks: result.rows, count: result.rows.length },
      message: `Found ${result.rows.length} task(s) in project ${projectId}.`,
    };
  } catch (err: unknown) {
    return {
      success: false,
      action: 'list_tasks',
      message: 'Failed to list tasks.',
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

