/** Names of every dispatchable platform command (the parity guard's source of truth). */
export const COMMAND_HANDLER_NAMES: string[] = Object.keys(COMMAND_HANDLERS);

function isPositiveIntegerId(value: unknown): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value > 0;
}

export function validateCommandContext(ctx: CommandContext): string | null {
  if (!isPositiveIntegerId(ctx.userId)) return 'userId must be a positive integer';
  if (!isPositiveIntegerId(ctx.organizationId)) {
    return 'organizationId must be a positive integer';
  }
  if (ctx.activeProjectId !== undefined && !isPositiveIntegerId(ctx.activeProjectId)) {
    return 'activeProjectId must be a positive integer when provided';
  }
  return null;
}

/**
 * Execute parsed commands and return results.
 */
export async function executeCommands(
  commands: ParsedCommand[],
  ctx: CommandContext
): Promise<CommandResult[]> {
  const results: CommandResult[] = [];

  // Identity is a dispatcher precondition, not merely an RBAC concern. Reject
  // every command before tenant policy reads, Part 11 reads, authorization, or
  // handler invocation when the verified principal context is invalid.
  const contextError = validateCommandContext(ctx);
  if (contextError) {
    return commands.map(cmd => ({
      success: false,
      action: cmd.command,
      message: `Command blocked: ${contextError}.`,
      error: 'COMMAND_CONTEXT_INVALID',
    }));
  }

  // ── Load per-tenant AnA tool policy once per dispatch ──
  // Stamps ctx.anaToolPolicy from organizations.settings.anaToolPolicy.
  // The policy gate in mdx-tool-policy.ts reads from this cached value;
  // populating it here means handlers don't need to know about the load.
  //
  // FAIL-CLOSED: this used to swallow read errors into {} (allow-all), so a
  // transient DB fault silently removed the tenant's deny/allow lists from
  // every governed mutation. The strict loader propagates the error and we
  // record the indeterminate state instead of inventing a permissive default.
  if (
    ctx.anaToolPolicy === undefined &&
    ctx.organizationId !== undefined &&
    Number.isFinite(ctx.organizationId)
  ) {
    try {
      if (!pool) throw new Error('no db pool available for AnA governance load');
      ctx.anaToolPolicy = await loadAnaToolPolicyStrict(pool, ctx.organizationId);
    } catch {
      ctx.governanceUnavailable = true;
    }
  }

  // ── Load per-tenant Part 11 enforcement flag once per dispatch ──
  // Stamps ctx.part11Enforce from organizations.settings.anaPart11Enforce.
  //
  // FAIL-CLOSED: this used to swallow read errors into `false` (not enforced),
  // which meant a settings-DB outage removed the 21 CFR Part 11 sign-off gate
  // from record-altering commands at exactly the moment the system was least
  // trustworthy. A determinate "tenant has not opted in" still yields false.
  if (
    ctx.part11Enforce === undefined &&
    ctx.organizationId !== undefined &&
    Number.isFinite(ctx.organizationId)
  ) {
    try {
      if (!pool) throw new Error('no db pool available for Part 11 governance load');
      ctx.part11Enforce = await loadPart11EnforceStrict(pool, ctx.organizationId);
    } catch {
      ctx.governanceUnavailable = true;
    }
  }

  const commandMap: Record<string, any> = COMMAND_HANDLERS;

  for (const cmd of commands) {
    const handler = commandMap[cmd.command];
    if (handler) {
      // ── Part 11 gate: governed record-altering commands fail closed unless
      // this dispatch carries a valid sign-off. Tiered — reason-for-change
      // always; high-impact actions additionally require an e-signature. ──
      if (ctx.part11Enforce && requiresPart11Signoff(cmd.command)) {
        const v = validateSignoff(ctx.signoff, {
          requireSignature: requiresEsignature(cmd.command, cmd.params as Record<string, unknown>),
        });
        if (!v.ok) {
          const blocked = buildSignatureRequiredResult(cmd.command, v, cmd.params as Record<string, unknown>);
          results.push(blocked);
          console.log(`[AnA Command] Blocked ${cmd.command}: PART11_SIGNATURE_REQUIRED (${v.code})`);
          continue;
        }
      }

      // ── Central authorization gate ────────────────────────────────────
      // The single place every AnA-dispatched command is authorized, for all
      // four entry points (chat bridge tool, POST /execute, POST
      // /governed-action, chat action blocks). Fail-closed by construction:
      // a command with no entry in COMMAND_AUTHORIZATION is denied, so a new
      // handler cannot ship ungated. Mutations additionally require the
      // caller's canonical organization_users role (via rbacService) and a
      // RESOLVED governance configuration. See command-rbac.ts.
      //
      // Deliberately AFTER the Part 11 gate: both are fail-closed pre-handler
      // gates, and this ordering keeps the Part 11 signature demand as the
      // first thing a signer is told when enforcement is on.
      const authz = await authorizeCommand(cmd.command, ctx);
      if (!authz.ok) {
        results.push(authz.result);
        console.warn(`[AnA Command] Blocked ${cmd.command}: ${authz.result.error}`);
        continue;
      }

      // ── Propose-only gate: an agent may ask, a person must act. ─────────
      // LAST of the pre-handler gates, immediately before execution. Ordering
      // matters and was chosen deliberately:
      //   · after authorizeCommand, so a caller who simply lacks the role is
      //     told that, not "a human must confirm" — and so an unreadable
      //     governance configuration still reports GOVERNANCE_UNAVAILABLE;
      //   · after the Part 11 block, so a signer mid-ceremony still gets the
      //     signature demand first;
      //   · but still before the handler, which is the only thing that matters
      //     for the guarantee.
      //
      // It is unconditional — unlike the Part 11 block, which is per-tenant and
      // defaults OFF, and unlike the params.confirm convention, which the model
      // can satisfy by asserting it. Three approve-class commands sit in
      // neither Part 11 set, so this is the only gate that reaches them.
      if (isProposeOnlyCommand(cmd.command) && ctx.humanConfirmed !== true) {
        results.push(proposalFor(cmd.command, cmd.params as Record<string, unknown> | undefined, ctx));
        continue;
      }

      try {
        const result = await handler(ctx, cmd.params);
        results.push(result);
        console.log(
          `[AnA Command] Executed ${cmd.command}: ${result.success ? 'OK' : 'FAILED'} — ${
            result.message
          }`
        );
      } catch (err: unknown) {
        results.push({
          success: false,
          action: cmd.command,
          message: `Execution failed: ${err instanceof Error ? err.message : String(err)}`,
        });
      }
    }
  }
  return results;
}

/**
 * What a propose-only command dispatched without a person's confirmation comes
 * back as: the proposal, its proposer sealed into its params so the
 * confirmation records which model wrote it (proposal-seal.ts) — or, for
 * model-authored text bound for a governed record from a model not qualified
 * for high-risk drafting (RULE 2), a refusal (D5, MC-RL-4, 2026-10-05; the
 * same rule AnaToolExecutor applies to tools). A proposal with no serving
 * model is a person's own command.
 */
function proposalFor(command: string, params: Record<string, unknown> | undefined, ctx: CommandContext): CommandResult {
  const proposed = params ?? {};
  if (ctx.servingModel && carriesModelAuthoredText(proposed) && !isServedModelApprovedForHighRisk(ctx.servingModel)) {
    console.info(`[AnA Command] Refused ${command}: MODEL_NOT_APPROVED_FOR_GOVERNED_WRITE`);
    return {
      success: false,
      action: command,
      error: 'MODEL_NOT_APPROVED_FOR_GOVERNED_WRITE',
      message:
        'This proposal holds text written by a model that is not approved for regulatory drafting, so it ' +
        'cannot become a governed record. Nothing was proposed or saved.',
    };
  }
  console.log(`[AnA Command] Proposed ${command}: HUMAN_CONFIRMATION_REQUIRED`);
  return buildHumanConfirmationRequiredResult(command, sealProposalParams(command, proposed, ctx));
}

/**
 * Process response text: parse command blocks, execute them, return results.
 */
export async function processCommandsInResponse(
  responseText: string,
  ctx: CommandContext
): Promise<{ executedCommands: CommandResult[]; cleanedText: string }> {
  const commands = parseCommandBlocks(responseText);
  if (commands.length === 0) return { executedCommands: [], cleanedText: responseText };

  const executedCommands = await executeCommands(commands, ctx);

  // Strip command blocks from response text (user doesn't need to see raw JSON)
  const cleanedText = responseText.replace(/```command\s*\n[\s\S]*?```/g, '').trim();

  return { executedCommands, cleanedText };
}
